from openpyxl import load_workbook

# Load the workbook
wb = load_workbook("input.xlsx")
ws = wb.active

# Extract company data from row 11
companies = {}
for col in range(1, 9):
    company = ws.cell(row=11, column=col).value
    if company:
        companies[company] = []

# Extract country data from row 1
countries = []
for col in range(2, 9):
    country = ws.cell(row=1, column=col).value
    if country:
        countries.append(country)

# Extract employee data for each company
for row in range(12, 14):
    company = ws.cell(row=row, column=1).value
    for col in range(2, 9):
        employee_count = ws.cell(row=row, column=col).value
        if employee_count and employee_count > 0:
            countries_index = col - 2
            if countries_index < len(countries):
                country = countries[countries_index]
                companies[company].append(country)

# Write the number of countries each company operates in
for i, (company, country_list) in enumerate(companies.items()):
    ws.cell(row=12 + i, column=9).value = len(country_list)

# Save the workbook
wb.save("output.xlsx")
