from openpyxl import load_workbook

# Load the workbook and select the active sheet
wb = load_workbook("input.xlsx")
ws = wb.active

# Define the ranges
month_names = [ws[f"B{i}"].value for i in range(3, 15)]  # B3:B14
month_end_dates = [ws[f"B{i}"].value for i in range(17, 25)]  # B17:B24
data_values = [[ws.cell(row=i, column=j).value for j in range(3, 8)] for i in range(17, 25)]  # C17:G24

# Map each month name to its corresponding end date
month_to_date = {}
for month, date in zip(month_names, month_end_dates):
    if month and date:
        month_to_date[month] = date

# Create a dictionary to map each month to its data values
month_to_data = {}
for i, month in enumerate(month_names):
    if month:
        month_to_data[month] = data_values[i]

# Calculate totals for each month and write to C3:G14
for row_idx, month in enumerate(month_names, start=3):
    if month not in month_to_date or month not in month_to_data:
        continue
    data = month_to_data[month]
    total = sum(value for value in data if value is not None)
    if total > 0:
        ws[f"C{row_idx}"] = total
    else:
        ws[f"C{row_idx}"] = ""

# Save the workbook
wb.save("output.xlsx")
